import SwiftUI
import AppKit

struct DatasetsView:View{
 @EnvironmentObject var work:Workspace;@State private var query="";@State private var tag="";@State private var keyword="";@State private var category="";@State private var source="";@State private var rating="";@State private var offset=0
 @State private var bodyText="{}";@State private var tags="";@State private var keywords="";@State private var summary="";@State private var itemCategory="";@State private var itemRating=0;@State private var linkTarget="";@State private var linkType="related";@State private var links:[[String:Any]]=[];@State private var outcomes:[[String:Any]]=[]
 var current:[String:Any]?{work.items.first{$0["id"] as? String==work.selectedItem}}
 var filters:[String:Any]{var f:[String:Any]=["query":query,"tag":tag,"keyword":keyword,"category":category,"source":source,"offset":offset,"limit":10];if let n=Int(rating){f["rating"]=n};return f}
 var body:some View{VStack(alignment:.leading,spacing:12){HStack{Button("Collect data",systemImage:"text.bubble"){work.selectedSession="";work.section="Agents"};Picker("Revision",selection:$work.selectedRevision){ForEach(work.revisions,id:\.recordId){r in Text("\(r["name"] ?? "Dataset") · \((r["id"] as? String ?? "").prefix(10)) · \(r["count"] ?? 0) records").tag(r.recordId)}};Button("Verify revision"){Task{if let r=await work.request("verify",["revision":work.selectedRevision]){work.notice="Verified revision: \(r["records"] ?? 0) records; SQLite and JSONL integrity passed."}}}.disabled(work.selectedRevision.isEmpty)}
 if !work.imports.isEmpty{DisclosureGroup("Background imports"){ForEach(work.imports,id:\.recordId){r in HStack{FieldView(field:Field("import.state","Import",r["state"] ?? "unknown",meaning:"Durable background copy into a new revision, without modifying the source."));FieldView(field:Field("import.processed","Records copied",r["processed"] ?? 0,meaning:"Full source records copied so far; not just previews."));Text(r["name"] as? String ?? "").font(.caption);if let error=r["error"] as? String{Text(error).font(.caption).foregroundStyle(.orange)};if ["failed","interrupted"].contains(r["state"] as? String ?? ""){Button("Resume import"){Task{_ = await work.request("import-resume",["id":r.recordId]);await work.datasets()}}}}}}}
 HStack{TextField("Search records",text:$query);TextField("Tag",text:$tag);TextField("Keyword",text:$keyword);TextField("Category",text:$category);TextField("Source",text:$source);TextField("Rating",text:$rating).frame(width:55);Button("Filter"){offset=0;Task{await work.datasetPage(filters)}}}
 HSplitView{VStack(alignment:.leading){List(selection:$work.selectedItem){ForEach(work.items,id:\.recordId){item in VStack(alignment:.leading,spacing:4){Text((item["body"] as? [String:Any])?["id"].map{String(describing:$0)} ?? item["source"] as? String ?? String(item.recordId.prefix(20))).font(.caption.monospaced()).lineLimit(1);Text(item["summary"] as? String ?? item["source"] as? String ?? "Record").font(.caption).foregroundStyle(.secondary).lineLimit(2)}.tag(item.recordId)}};HStack{Button("Previous"){offset=max(0,offset-10);Task{await work.datasetPage(filters)}}.disabled(offset==0);Button("Next"){offset+=10;Task{await work.datasetPage(filters)}}.disabled(work.items.count<10)}}.frame(minWidth:210,maxWidth:300)
 if let item=current{ScrollView{VStack(alignment:.leading,spacing:12){FieldView(field:Field("record.id","Object ID",item.recordId,meaning:"Stable dataset record identity. Links use this ID across revisions."));Text("Edit a new revision").font(.headline);TextEditor(text:$bodyText).font(.system(.caption,design:.monospaced)).frame(minHeight:220);Button("Save as child revision"){Task{do{let value=try JSONSerialization.jsonObject(with:Data(bodyText.utf8),options:.fragmentsAllowed);if let r=await work.request("edit",["revision":work.selectedRevision,"id":work.selectedItem,"body":value]){work.selectedRevision=r["id"] as? String ?? work.selectedRevision;await work.datasets();await work.datasetPage(filters);work.notice="New revision saved; original sources and parent revision preserved."}}catch{work.error=error.localizedDescription}}};Divider();Text("Annotations").font(.headline);TextField("Tags, comma separated",text:$tags);TextField("Keywords, comma separated",text:$keywords);TextField("Summary",text:$summary);HStack{TextField("Category",text:$itemCategory);Stepper("Rating \(itemRating)",value:$itemRating,in:0...5)};Button("Save annotations"){Task{_ = await work.request("annotate",["id":work.selectedItem,"values":["tags":list(tags),"keywords":list(keywords),"summary":summary,"category":itemCategory,"rating":itemRating]]);await work.datasetPage(filters)}};Divider();Text("Linked objects").font(.headline);HStack{TextField("Target object ID",text:$linkTarget);TextField("Relationship",text:$linkType);Button("Link"){Task{if let r=await work.request("link",["from":work.selectedItem,"to":linkTarget,"kind":linkType]){links=r["links"] as? [[String:Any]] ?? []}}}};ForEach(Array(links.enumerated()),id:\.offset){_,link in FieldView(field:Field("record.link","Relationship",Workspace.pretty(link),meaning:"Explicit link between stable record IDs. Raw records are not changed."))}}.padding(8)}}else{ContentUnavailableView("Choose a dataset record",systemImage:"point.3.connected.trianglepath.dotted",description:Text("Import source records in Data explorer, then annotate, link or create edited revisions."))}}
 }.task{await work.datasets();await work.datasetPage(filters)}.onChange(of:work.selectedRevision){_,_ in offset=0;Task{await work.datasetPage(filters)}}.onChange(of:work.selectedItem){_,_ in fill()}.onChange(of:work.items.count){_,_ in fill()}
 }
 func list(_ s:String)->[String]{s.split(separator:",").map{$0.trimmingCharacters(in:.whitespaces)}.filter{!$0.isEmpty}}
 func fill(){guard let item=current else{return};bodyText=Workspace.pretty(item["body"] ?? [:]);tags=(item["tags"] as? [String] ?? []).joined(separator:", ");keywords=(item["keywords"] as? [String] ?? []).joined(separator:", ");summary=item["summary"] as? String ?? "";itemCategory=item["category"] as? String ?? "";itemRating=item["rating"] as? Int ?? 0;Task{if let r=await work.request("links",["id":work.selectedItem]){links=r["links"] as? [[String:Any]] ?? []}}}
}
extension Dictionary where Key==String,Value==Any{var recordId:String{self["id"] as? String ?? ""}}
